/**
 * FeedbackModal — 反馈弹窗。
 * 参考 dify 的 Dialog + Textarea 模式，纯 Tailwind 实现。
 */
import { useState, useEffect, useRef } from 'react'

interface FeedbackModalProps {
  open: boolean
  onClose: () => void
  onSubmit: (comment: string) => void
}

export function FeedbackModal({ open, onClose, onSubmit }: FeedbackModalProps) {
  const [comment, setComment] = useState('')
  const textareaRef = useRef<HTMLTextAreaElement>(null)

  useEffect(() => {
    if (open) {
      setComment('')
      setTimeout(() => textareaRef.current?.focus(), 100)
    }
  }, [open])

  // ESC 关闭
  useEffect(() => {
    if (!open) return
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', handleKey)
    return () => window.removeEventListener('keydown', handleKey)
  }, [open, onClose])

  if (!open) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* 背景遮罩 */}
      <div
        className="absolute inset-0 bg-black/40 backdrop-blur-sm"
        onClick={onClose}
      />
      {/* 弹窗内容 */}
      <div className="relative w-full max-w-md rounded-xl border bg-background p-6 shadow-lg">
        <h3 className="text-lg font-semibold mb-1">提供反馈</h3>
        <p className="text-sm text-muted-foreground mb-4">
          请描述您遇到的问题或建议，帮助我们改进。
        </p>
        <textarea
          ref={textareaRef}
          value={comment}
          onChange={(e) => setComment(e.target.value)}
          rows={4}
          placeholder="请描述您的问题..."
          className="w-full resize-none rounded-lg border bg-background px-3 py-2 text-sm outline-none placeholder:text-muted-foreground focus:ring-2 focus:ring-ring"
        />
        <div className="mt-4 flex justify-end gap-2">
          <button
            onClick={onClose}
            className="rounded-lg border px-4 py-2 text-sm hover:bg-accent transition-colors"
          >
            取消
          </button>
          <button
            onClick={() => { onSubmit(comment); onClose() }}
            className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground hover:bg-primary/90 transition-colors"
          >
            提交
          </button>
        </div>
      </div>
    </div>
  )
}
